p=dist/'assets/sources.json';d=json.loads(p.read_text());assert not any(x['id']=='SW01' for x in d);f=dest/'THEOREM.md';d.append({'id':'SW01','title':'Source-to-path spectral leakage theorem v0.1','group':'Recent amendments','status':'CONDITIONAL THEOREM / PROPOSED WITNESSES / PHYSICAL PROMOTION0','note':'Full-input image and polynomial distortion; exact proposed design; all physical witnesses missing.','url':'/evidence/source-witness/','local':'/sources/source-witness-v0.1/THEOREM.md','sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'size_bytes':f.stat().st_size,'content':f.read_text()});p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
